        ctx.fillText(`STATUS:`, 20, 50);
        ctx.fillStyle = '#f8fafc'; 
        ctx.fillText(agent.btStatus || 'IDLE', 70, 50);
        const startX = 50;
        const startY = 90;
        const gap = 80;
